.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #0b0b0b;
  --vt-ink: #1a1a1a;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #1a1a1a;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #fdb92d;
  --vt-line: rgba(26, 26, 26, 0.14);
  color: var(--vt-ink);
  background: var(--vt-surface);
  font-family: 'Manrope', 'Alegreya', sans-serif;
  line-height: 1.6;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root img {
  display: block;
  max-width: 100%;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  font-family: 'Alegreya', serif;
  color: var(--vt-ink);
  font-weight: 800;
  line-height: 1.15;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 280px;
  background: var(--vt-accent);
  border-right: 1px solid var(--vt-line);
  padding: 48px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-y: auto;
  z-index: 100;
  text-align: center;
}

.logo {
  display: inline-flex;
  margin-bottom: 56px;
}

.logoBrand {
  display: block;
  max-width: 130px;
  height: auto;
}

.navLinks {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
}

.navLinks a {
  color: var(--vt-on-accent);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 10px 16px;
  border-radius: 999px;
  transition: background 0.3s, color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-on-deep);
  background: var(--vt-accent-ink);
}

.main {
  margin-left: 280px;
  min-height: 100vh;
  background: var(--vt-surface);
}

.hero {
  position: relative;
  min-height: 720px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background-color: var(--vt-surface-deep);
  background-size: cover;
  background-position: center;
  border-bottom: 12px solid var(--vt-accent);
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--vt-surface-deep) 0%, var(--vt-accent-on-deep) 100%);
  opacity: 0.72;
}

